-- Site settings: fill blanks only.
update public.site_settings set
  site_name = coalesce(nullif(site_name, ''), 'Anastasia Patience'),
  tagline = coalesce(nullif(tagline, ''), 'Find your reason to smile.'),
  default_seo_title = coalesce(nullif(default_seo_title, ''), 'Anastasia Patience'),
  default_seo_description = coalesce(nullif(default_seo_description, ''), 'Author, storyteller and founder of Patience Media House. Books, an audiobook in her own voice, and letters on faith, loss and building a life you love.'),
  footer_text = coalesce(nullif(footer_text, ''), 'Written and read in Cyprus, with love.'),
  social_image_id = coalesce(social_image_id, (select id from public.media_assets where id = '5eed0000-0000-4000-8000-000000000015'::uuid))
where id = 'site';

-- Pages.
insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/', 'home', true, 'Home', 'Anastasia Patience: Find Your Reason to Smile', 'Author, storyteller and founder of Patience Media House. Books, an audiobook in her own voice, and letters on faith, loss and building a life you love.', 'published', now(), replace('[{"id":"c0de0001-0000-4000-8000-3fb031d9a261","type":"hero","variant":"portrait_arch","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"Author · Storyteller · Founder of Patience Media House","title":"Turning pain into purpose.","accent":"purpose","body":"I''m Anastasia. I help women turn their scars into stories, their stories into skills, and their skills into a life they love.","imageMediaId":"5eed0000-0000-4000-8000-000000000001","caption":"","primary":{"label":"Read my story","href":"/about"},"secondary":{"label":"Get the free ebook","href":"#free-ebook"},"listenCta":true}},{"id":"c0de0002-0000-4000-8000-739d853cb657","type":"audiobook_player","variant":"shelf","settings":{"hidden":false,"anchor":"listen","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"Listen","title":"Hear it in her own voice.","intro":"The first chapters are free. Press play and keep reading the site; the story follows you.","audiobookIds":[]}},{"id":"c0de0003-0000-4000-8000-afe291ca4040","type":"featured_book","variant":"cover_left","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"bookId":"b00c0000-0000-4000-8000-000000000001","eyebrow":"The book","quote":"","quoteBy":"","showEbookGate":true}},{"id":"c0de0004-0000-4000-8000-d6f2af9f5906","type":"two_column","variant":"image_right","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"cream"},"props":{"eyebrow":"Who I am","title":"A woman who chose joy, on purpose.","body":"<p>I write for the woman rebuilding after loss, the mother whispering prayers over a sick child, the entrepreneur with a dream she is afraid to name.</p><p>My story is stitched together from grief, faith and stubborn hope, and every book, masterclass and letter I make is a hand extended back to you.</p>","imageMediaId":"5eed0000-0000-4000-8000-000000000002","link":{"label":"My story","href":"/about"}}},{"id":"c0de0005-0000-4000-8000-593497ca6205","type":"testimonials","variant":"single","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"","title":"","bookId":null,"testimonialIds":[]}},{"id":"c0de0006-0000-4000-8000-227fc8ac14d5","type":"latest_posts","variant":"list","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"The journal","title":"Letters from the honest middle.","categoryId":null,"count":3,"showCategories":true,"link":{"label":"All letters","href":"/blog"}}},{"id":"c0de0007-0000-4000-8000-15a0615c7f01","type":"video","variant":"latest","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"cocoa"},"props":{"eyebrow":"Videos","title":"On stage, on camera, on purpose.","videoIds":[],"channelLink":{"label":"","href":""}}},{"id":"c0de0008-0000-4000-8000-56a7367985e7","type":"call_to_action","variant":"band","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"cream"},"props":{"eyebrow":"Patience Humanitarian Foundation","title":"Where no one feels left behind.","body":"Food assistance, compassionate care, community support and care for rescued animals: the work my story led me to.","link":{"label":"Visit the foundation","href":"/foundation"}}}]', 'b00c0000-0000-4000-8000-000000000001', coalesce((select id::text from public.books where slug = 'find-your-reason-to-smile'), 'b00c0000-0000-4000-8000-000000000001'))::jsonb)
on conflict (path) do nothing;

insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/about', 'standard', false, 'About', 'About Anastasia Patience', 'From Ghana to Cyprus, through loss, faith and motherhood: how Anastasia became an author, a storyteller and the founder of Patience Media House.', 'published', now(), '[{"id":"c0de0009-0000-4000-8000-37386409c9a5","type":"hero","variant":"portrait_arch","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"Meet Anastasia","title":"A life rewritten in the margins.","accent":"rewritten","body":"I am a daughter of Ghana, a woman of Cyprus, a mother by miracle and a storyteller by calling. This is the long version.","imageMediaId":"5eed0000-0000-4000-8000-000000000003","caption":"","primary":{"label":"","href":""},"secondary":{"label":"","href":""},"listenCta":false}},{"id":"c0de0019-0000-4000-8000-fa1ba26418e9","type":"timeline","variant":"vertical","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"The chapters","title":"Every season taught me something.","items":[{"id":"c0de0010-0000-4000-8000-b5ed4a6d3b17","label":"The beginning","title":"My parents","body":"My mother taught me to pray, and to stay quiet and steady in difficult times. My father taught me to work hard with discipline: to be polite, honest and respectful.","imageMediaId":null},{"id":"c0de0011-0000-4000-8000-ae8530938c91","label":"The crossing","title":"Two suitcases","body":"At twenty-four I boarded a plane with two suitcases and a promise. I would build a life. I would send money home. I would become someone.","imageMediaId":null},{"id":"c0de0012-0000-4000-8000-6bce208ef8b1","label":"The work","title":"Caregiver","body":"For years I cared for the elderly. Their stories became mine. Their loneliness taught me presence. Their courage taught me endurance.","imageMediaId":null},{"id":"c0de0013-0000-4000-8000-d93ff30ab137","label":"The first loss","title":"My brother","body":"When my younger brother died, something inside me broke that I didn''t know could break. I learned that grief has weather. Some days it rains and does not stop.","imageMediaId":null},{"id":"c0de0014-0000-4000-8000-57523512d4ef","label":"The unmooring","title":"Without parents","body":"Losing my mother years later left me unmoored. Without parents in a foreign country, I had to find my own way and become my own compass.","imageMediaId":null},{"id":"c0de0015-0000-4000-8000-f940ebd72f3e","label":"The choice","title":"The pregnancy","body":"The doctors said terminate. There were risks, reasons and papers to sign. I chose faith. I chose him, because I believed his life was worth fighting for, even when the world told me otherwise.","imageMediaId":null},{"id":"c0de0016-0000-4000-8000-e3d1000be6f8","label":"The miracle","title":"My son","body":"He came into this world small, quiet and perfect, already carrying a strength I could see in him. He is the reason I know God still writes stories with impossible endings.","imageMediaId":null},{"id":"c0de0017-0000-4000-8000-eae36bececd8","label":"The dark room","title":"Depression","body":"Postpartum depression came like a fog with no exit. I stopped smiling. I stopped writing. Slowly, gently, I found my way back.","imageMediaId":null},{"id":"c0de0018-0000-4000-8000-d116255ef41d","label":"Now","title":"Author and founder","body":"I write the books I needed. I teach the classes I wished I had. Find Your Reason to Smile is my letter to every woman who ever felt too broken to begin again.","imageMediaId":null}]}},{"id":"c0de0020-0000-4000-8000-30c12e9e2226","type":"quote","variant":"with_portrait","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"cream"},"props":{"quote":"To hand every woman a lantern for the dark seasons, and a map to build a life she loves once the light returns.","accent":"lantern","by":"My mission","imageMediaId":"5eed0000-0000-4000-8000-000000000004"}},{"id":"c0de0021-0000-4000-8000-a968612f8e1f","type":"rich_text","variant":"with_pull_quote","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"What I believe","title":"Every scar is a syllabus.","body":"<p>I believe every ordinary woman carries something the world needs, usually the very thing she thinks disqualifies her.</p><p>I have lived the long nights: the phone call that changes everything, the hospital corridor, the morning you cannot find a reason to get up. I have also lived the slow return, one small practice at a time, until joy was something I chose again rather than something I waited for.</p><p>That is what I write about, what I teach and why I started the foundation. Not because I have arrived, but because I know the way back, and I would rather walk it with you.</p>","pullQuote":"Every mother is a mystic. Every scar is a syllabus."}},{"id":"c0de0027-0000-4000-8000-340553f9ce6e","type":"list","variant":"plain","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"What I stand on","title":"Five values, one calling.","intro":"","items":[{"id":"c0de0022-0000-4000-8000-088bb16b469c","title":"Faith","body":"Faith is the muscle I train first, every morning."},{"id":"c0de0023-0000-4000-8000-3782e8c3d367","title":"Resilience","body":"Not the loud kind. The quiet, unglamorous, keep-going kind."},{"id":"c0de0024-0000-4000-8000-5846bf4eaeed","title":"Purpose","body":"Every scar is a syllabus. I teach what I have lived."},{"id":"c0de0025-0000-4000-8000-001024557545","title":"Story","body":"Stories heal what statistics cannot reach."},{"id":"c0de0026-0000-4000-8000-7db7997948eb","title":"Service","body":"If it does not help someone rise, I do not build it."}]}},{"id":"c0de0028-0000-4000-8000-3f315986e752","type":"call_to_action","variant":"card","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"The book","title":"Read the whole story.","body":"Find Your Reason to Smile is the memoir behind every chapter above, with the small daily practices that carried me back.","link":{"label":"About the book","href":"/books/find-your-reason-to-smile"}}}]'::jsonb)
on conflict (path) do nothing;

