values ('/books', 'collection', true, 'Books', 'Books by Anastasia Patience', 'Memoir, workbook and gentle wisdom: books to carry you through the seasons you cannot skip, in print, ebook and audio.', 'published', now(), replace('[{"id":"c0de0029-0000-4000-8000-590fbbf26360","type":"book_list","variant":"rows","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"The bookshelf","title":"Books to carry you home.","intro":"Part memoir, part manual, written in the voice of a friend who has walked it."}},{"id":"c0de0030-0000-4000-8000-45da0794983a","type":"audiobook_player","variant":"shelf","settings":{"hidden":false,"anchor":"listen","width":"default","spacing":"default","background":"cocoa"},"props":{"eyebrow":"Listen","title":"The audiobooks, read by the author.","intro":"","audiobookIds":[]}},{"id":"c0de0031-0000-4000-8000-952e2feba662","type":"ebook_gate","variant":"card","settings":{"hidden":false,"anchor":"free-ebook","width":"default","spacing":"default","background":"ivory"},"props":{"bookId":"b00c0000-0000-4000-8000-000000000001","eyebrow":"Free ebook","title":"A copy for you, free.","body":"The complete ebook of Find Your Reason to Smile. Tell me your first name so I know who it is for.","buttonLabel":"Send me the ebook"}}]', 'b00c0000-0000-4000-8000-000000000001', coalesce((select id::text from public.books where slug = 'find-your-reason-to-smile'), 'b00c0000-0000-4000-8000-000000000001'))::jsonb)
