insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/foundation', 'standard', false, 'Patience Humanitarian Foundation', 'Patience Humanitarian Foundation', 'Where no one feels left behind: food assistance, compassionate care, community support and care for rescued animals.', 'published', now(), '[{"id":"c0de0035-0000-4000-8000-be6feb5f61ae","type":"hero","variant":"portrait_arch","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"Patience Humanitarian Foundation","title":"Where no one feels left behind.","accent":"left behind","body":"We support individuals, families and vulnerable lives facing hardship, through food assistance, compassionate care, community outreach and care for rescued animals.","imageMediaId":"5eed0000-0000-4000-8000-000000000010","caption":"","primary":{"label":"Give","href":"#give"},"secondary":{"label":"Read their stories","href":"#stories"},"listenCta":false}},{"id":"c0de0040-0000-4000-8000-0d7d08b8c45e","type":"list","variant":"numbered","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"What we do","title":"Four ways we care.","intro":"","items":[{"id":"c0de0036-0000-4000-8000-8d6dc4914699","title":"Food assistance","body":"Groceries and warm meals for families who are going without."},{"id":"c0de0037-0000-4000-8000-5531dda3b168","title":"Compassionate care","body":"Visits, company and practical help for the elderly, the sick and the lonely."},{"id":"c0de0038-0000-4000-8000-3b24182e6513","title":"Community support","body":"Standing with families through hard seasons, so no one faces them alone."},{"id":"c0de0039-0000-4000-8000-3761675e9fc2","title":"Rescued animals","body":"Food, shelter and veterinary care for animals that have been abandoned."}]}},{"id":"c0de0041-0000-4000-8000-ab82aac60233","type":"donation","variant":"card","settings":{"hidden":false,"anchor":"give","width":"default","spacing":"default","background":"cream"},"props":{"eyebrow":"Give","title":"Together, we can make a difference.","body":"Every gift becomes a meal, a visit or a rescue. Give once, or walk with us every month.","amounts":[10,25,50,100],"allowMonthly":true}},{"id":"c0de0042-0000-4000-8000-d4e82792717b","type":"foundation_stories","variant":"grid","settings":{"hidden":false,"anchor":"stories","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"Impact stories","title":"Faces we hold close.","categoryId":null,"count":6}},{"id":"c0de0048-0000-4000-8000-8302fbd36ced","type":"list","variant":"plain","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"eyebrow":"Our values","title":"What guides every act of care.","intro":"","items":[{"id":"c0de0043-0000-4000-8000-bf1484f6fd81","title":"Compassion","body":"We meet people where they are."},{"id":"c0de0044-0000-4000-8000-37e532dad8bf","title":"Dignity","body":"Help is given with respect, and stories are shared only with permission."},{"id":"c0de0045-0000-4000-8000-902bf99ae7fa","title":"Service","body":"We show up, quietly and consistently."},{"id":"c0de0046-0000-4000-8000-2f48f213bab2","title":"Hope","body":"Every meal and every visit says: you are not forgotten."},{"id":"c0de0047-0000-4000-8000-fdf4487b3f0a","title":"Community","body":"None of this happens alone."}]}}]'::jsonb)
on conflict (path) do nothing;

