insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/start', 'links', true, 'Anastasia Patience', 'Start here: Anastasia Patience', 'Everything in one place: the free ebook, the audiobook, the journal, masterclasses and the foundation.', 'published', now(), (
    with old as (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', l.id, 'label', left(l.label, 80), 'description', left(coalesce(l.sub, ''), 140),
        'href', coalesce(l.to_path, l.href), 'featured', false
      ) order by l.sort_order), '[]'::jsonb) as items
      from public.start_page_links l
      where l.enabled
        and (l.to_path ~ '^/[a-z0-9/-]*$' or l.href ~ '^https://')
        and coalesce(l.to_path, l.href) not in ('/books#free-ebook', '/#listen', '/blog', '/masterclasses', '/foundation', '/books', '/masterclasses', '/blog', '/foundation')
    )
    select jsonb_set(s.v, '{0,props,items}', (s.v #> '{0,props,items}') || old.items)
    from old, (select '[{"id":"c0de0064-0000-4000-8000-d9701c181109","type":"link_list","variant":"stacked","settings":{"hidden":false,"anchor":"","width":"default","spacing":"default","background":"ivory"},"props":{"items":[{"id":"c0de0059-0000-4000-8000-77c34083d8c8","label":"Get the free ebook","description":"Find Your Reason to Smile, free to download","href":"/books#free-ebook","featured":true},{"id":"c0de0060-0000-4000-8000-096051a7e48e","label":"Listen to the audiobook","description":"The first chapters, read by Anastasia","href":"/#listen","featured":false},{"id":"c0de0061-0000-4000-8000-d947446e8947","label":"Read the journal","description":"Letters on faith, purpose and the honest middle","href":"/blog","featured":false},{"id":"c0de0062-0000-4000-8000-5c4840314426","label":"Masterclasses","description":"Turn what you know into income","href":"/masterclasses","featured":false},{"id":"c0de0063-0000-4000-8000-7c3a36122cfc","label":"Patience Humanitarian Foundation","description":"Where no one feels left behind","href":"/foundation","featured":false}],"showSocialLinks":true}}]'::jsonb as v) s
  ))
on conflict (path) do nothing;

insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/privacy', 'legal', true, 'Privacy', 'Privacy notice', 'What this website collects, why, who helps us run it, how long we keep it and your rights.', 'published', now(), '[{"id":"c0de0057-0000-4000-8000-418fbfe6fa29","type":"rich_text","variant":"one_column","settings":{"hidden":false,"anchor":"","width":"narrow","spacing":"default","background":"ivory"},"props":{"eyebrow":"","title":"","body":"<p>This website is run by Anastasia Patience and Patience Media House, based in Cyprus. This notice explains what we collect when you use it, why, and what you can ask us to do. To reach us about your data, use the <a href=\"/contact\">contact page</a>.</p><h2>What we collect</h2><ul><li><strong>Letters (newsletter):</strong> your email address and language. You confirm by email before we send anything (double opt-in).</li><li><strong>Free ebook:</strong> your first name, email and language, so we can send the download link. Ticking the letters box is separate and optional.</li><li><strong>Contact form:</strong> your name, email and message.</li><li><strong>Purchases and gifts:</strong> your name, email and, for printed books, your delivery address. Card details go straight to Stripe; we never see them.</li><li><strong>In your browser only:</strong> where you stopped in an audiobook chapter, your language choice and whether you dismissed a notice. These stay on your device and are never sent to us.</li></ul><h2>Why</h2><p>We use your details only to do what you asked: send the letters you confirmed, the ebook you requested, a reply to your message, or the order you paid for. We rely on your consent for the letters and on taking the steps you asked for everything else. Records of payments are kept because the law requires it.</p><h2>Who helps us run the site</h2><ul><li><strong>Supabase</strong> (database and file storage, in the EU)</li><li><strong>Cloudflare</strong> (hosting, and a check that forms are filled in by people)</li><li><strong>Stripe</strong> (payments)</li><li><strong>Resend</strong> (sending emails)</li><li><strong>Google</strong> (YouTube videos, which load only when you press play)</li></ul><p>We do not sell your data, and we do not use advertising or tracking cookies.</p><h2>How long we keep it</h2><ul><li>Unconfirmed newsletter sign-ups: deleted after 30 days.</li><li>Free ebook requests: 24 months, unless you also confirmed the letters.</li><li>Download links: they stop working after 7 days.</li><li>Contact messages: 24 months after we archive them.</li><li>Email delivery records: 12 months.</li><li>Orders and gifts: for as long as accounting law requires, after which names, emails and addresses are removed.</li></ul><h2>Your rights</h2><p>You can ask to see, correct or delete your data, or object to how we use it. Every letter has an unsubscribe link. If you are unhappy with how we handled your data, you can complain to the Commissioner for Personal Data Protection in Cyprus.</p>","pullQuote":""}}]'::jsonb)
on conflict (path) do nothing;

insert into public.pages (path, kind, locked, title, seo_title, seo_description, status, published_at, sections)
values ('/terms', 'legal', true, 'Terms', 'Terms of use', 'The terms for using this website, buying from it and giving through it.', 'published', now(), '[{"id":"c0de0058-0000-4000-8000-6ae4e5cc4de8","type":"rich_text","variant":"one_column","settings":{"hidden":false,"anchor":"","width":"narrow","spacing":"default","background":"ivory"},"props":{"eyebrow":"","title":"","body":"<p>By using this website you agree to these terms. If anything is unclear, please <a href=\"/contact\">get in touch</a>.</p><h2>Words and pictures</h2><p>The writing, recordings and photographs on this site belong to Anastasia Patience unless credited otherwise. You are welcome to share links and short quotations with credit. Please ask before reusing anything else.</p><h2>Digital purchases</h2><p>Ebooks, audio and other digital products are delivered as soon as payment is confirmed, through a download link that works for 7 days. When you buy, you agree that delivery starts straight away, which means the usual 14-day right to cancel ends once the download begins. If a file does not work, tell us and we will fix it or refund you.</p><h2>Printed books</h2><p>Printed books bought through other shops are covered by that shop''s terms.</p><h2>Gifts to the foundation</h2><p>Gifts are used for the foundation''s work. If you gave by mistake, contact us within 30 days and we will refund you. Monthly gifts can be changed or cancelled at any time from the link in your receipt.</p><h2>Masterclasses</h2><p>Each masterclass page sets out what is included, the dates and how to cancel.</p><h2>The law</h2><p>These terms are governed by the laws of the Republic of Cyprus. Nothing here limits your rights as a consumer.</p>","pullQuote":""}}]'::jsonb)
on conflict (path) do nothing;

-- Menus, only when there are none yet.
do $$
declare
  _parent uuid;
begin
  if exists (select 1 from public.navigation_items) then
    return;
  end if;

  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Books', (select id from public.pages where path = '/books'), null, null, 0);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'About', (select id from public.pages where path = '/about'), null, null, 1);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Journal', (select id from public.pages where path = '/blog'), null, null, 2);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Foundation', (select id from public.pages where path = '/foundation'), null, null, 3);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header', 'Contact', (select id from public.pages where path = '/contact'), null, null, 4);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('header_action', 'Free ebook', null, '/books#free-ebook', null, 5);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('footer', 'Read', null, '/books', null, 6)
  returning id into _parent;
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position) values
    ('footer', 'Books', (select id from public.pages where path = '/books'), null, _parent, 0),
    ('footer', 'Journal', (select id from public.pages where path = '/blog'), null, _parent, 1),
    ('footer', 'Gallery', (select id from public.pages where path = '/gallery'), null, _parent, 2);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('footer', 'Learn', null, '/masterclasses', null, 7)
  returning id into _parent;
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position) values
    ('footer', 'Masterclasses', (select id from public.pages where path = '/masterclasses'), null, _parent, 0),
    ('footer', 'Shop', (select id from public.pages where path = '/shop'), null, _parent, 1),
    ('footer', 'Start here', (select id from public.pages where path = '/start'), null, _parent, 2);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('footer', 'Foundation', null, '/foundation', null, 8)
  returning id into _parent;
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position) values
    ('footer', 'Our work', (select id from public.pages where path = '/foundation'), null, _parent, 0),
    ('footer', 'Give', null, '/foundation#give', _parent, 1),
    ('footer', 'Contact', (select id from public.pages where path = '/contact'), null, _parent, 2);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('legal', 'Privacy', (select id from public.pages where path = '/privacy'), null, null, 9);
  insert into public.navigation_items (menu, label, page_id, url, parent_id, position)
  values ('legal', 'Terms', (select id from public.pages where path = '/terms'), null, null, 10);
end;
$$;

-- Social links from the old start page, when there are none yet.
insert into public.social_links (platform, url, label, position)
select p.platform, s.url, '', s.sort_order
from public.start_page_socials s
cross join lateral (
  select case lower(s.platform)
    when 'twitter' then 'x'
    when 'x' then 'x'
    else lower(s.platform)
  end as platform
) p
where s.enabled
  and s.url ~ '^https://'
  and p.platform in ('instagram', 'facebook', 'youtube', 'tiktok', 'x', 'linkedin', 'threads', 'spotify')
  and not exists (select 1 from public.social_links);

-- Praise: the reader reviews already on the live site, when there is none yet.
insert into public.testimonials (quote, name, role, book_id, published, position)
select r.quote,
  btrim(split_part(r.by_name, ',', 1)),
  btrim(substr(r.by_name, length(split_part(r.by_name, ',', 1)) + 2)),
  r.book_id, r.published, r.sort_order
from public.book_reviews r
where r.published and not exists (select 1 from public.testimonials);

-- Consent wording, version 1.
insert into public.consent_texts (key, version, body) values
  ('newsletter', 1, 'Send me Anastasia''s letters by email. I can unsubscribe at any time with the link in every letter.'),
  ('ebook_gate', 1, 'We use your first name and email to send you the ebook. We keep them for 24 months, or longer if you also join the letters.'),
  ('contact', 1, 'We use your name, email and message only to reply to you.'),
  ('checkout', 1, 'Your order details are used to deliver what you bought and kept as the law requires for accounting.'),
  ('donation', 1, 'Your details are used to process your gift and send your receipt, and kept as the law requires for accounting.')
on conflict (key, version) do nothing;

